mapper.select:
select RTN_REP_MES_NO, SEND_REP_MES_NO, REPORT_SEND_DATE, REPORT_ACCEPT_DATE, BUSINESS_GROUP_TYPE, REPORT_ETR_TYPE, FILE_ID, FILE_NAME, FILE_PATH, HANDLE_STATUS, MOVE_FLAG, MOVE_PATH, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME,FEEDBACK_MSG from CHB_FEEDBACK_FILE cff where 1=1
AND cff.REPORT_ETR_TYPE = #{reportEtrType}
AND cff.HANDLE_STATUS = #{handleStatus}
AND cff.REPORT_SEND_DATE >= STR_TO_DATE(#{reportSendDate}, '%Y-%m-%d %H:%i:%s')
AND cff.REPORT_ACCEPT_DATE >= STR_TO_DATE(#{reportAcceptDate}, '%Y-%m-%d %H:%i:%s')

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, CONCAT_WS(',',ASSET_CODE,DATE_FORMAT(VAL_DATE, '%Y-%m-%d')) keyCode from CHB_AST_VAL_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_REGIST_CODE keyCode from CHB_PRD_ISSUE_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_INS_ID keyCode from CHB_PRD_DECLARE_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_ID keyCode from CHB_PRD_RAISETOT_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_REGIST_CODE||','||TO_CHAR(MDATE, 'yyyy-MM-dd') keyCode from CHB_PRD_DEAL_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, PROD_REGIST_CODE keyCode from CHB_PRD_END_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, CONCAT_WS(',',PLAN_ASSET_ID,CONCAT_WS(',', ASSET_CODE, DATE_FORMAT(POS_DATE, '%Y-%m-%d'))) keyCode from CHB_BOT_AST_POS_SUB where SUMIT_SEQ in
#{seqno}
