select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, TRADE_CODE keyCode from CHB_INVEST_TRADE_SUB where SUMIT_SEQ in
#{seqno}
