select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, ASSET_CODE keyCode from CHB_ASSET_INFO_SUB where SUMIT_SEQ in
#{seqno}
order by SUMIT_SEQ

select SUMIT_SEQ regSeqno, SEND_STATUS regRepStatus, SUBMIT_FEEDBACK_STATUS regFeedbackStatus, STATUS_DATE regDataDate, STATUS regDataStatus, CONCAT_WS(',',EMPLOYEE_TYPE,IDENTIFY_NUMBER) keyCode from CHB_EMPLOYEE_INFO_SUB where SUMIT_SEQ in
#{seqno}
