mapper.insert:
insert into CHB_INFO_REPORT(REPORT_NO,REP_MES_NO,UPLOAD_RESULT,UPLOAD_RESULT_MSG, UPLOAD_FILE_ID,CHECK_FILE_ID,CHECK_RESULT,CHECK_RESULT_MSG, CHECK_FILE_NAME,CHECK_TOTAL_COUNT,CHECK_SUCCESS_COUNT,CHECK_FAILED_COUNT, INSIDE_FILE_ID,SEND_TIME,REPLY_TIME,WORKFLOW_ID,CREATE_USER, CREATE_DEPT,CREATE_TIME,UPDATE_USER,UPDATE_TIME,SUBMIT_COUNT,SUBMIT_TYPE) select de.* from ( select TEMP.* from (
select #{item.reportNo,jdbcType=VARCHAR} REPORT_NO, #{item.repMesNo,jdbcType=VARCHAR} REP_MES_NO, #{item.uploadResult,jdbcType=VARCHAR} UPLOAD_RESULT, #{item.uploadResultMsg,jdbcType=VARCHAR} UPLOAD_RESULT_MSG, #{item.uploadFileId,jdbcType=VARCHAR} UPLOAD_FILE_ID, #{item.checkFileId,jdbcType=VARCHAR} CHECK_FILE_ID, #{item.checkResult,jdbcType=VARCHAR} CHECK_RESULT, #{item.checkResultMsg,jdbcType=VARCHAR} CHECK_RESULT_MSG, #{item.checkFileName,jdbcType=VARCHAR} CHECK_FILE_NAME, #{item.checkTotalCount,jdbcType=DECIMAL} CHECK_TOTAL_COUNT, #{item.checkSuccessCount,jdbcType=DECIMAL} CHECK_SUCCESS_COUNT, #{item.checkFailedCount,jdbcType=DECIMAL} CHECK_FAILED_COUNT, #{item.insideFileId,jdbcType=VARCHAR} INSIDE_FILE_ID, #{item.sendTime,jdbcType=DATE} SEND_TIME, #{item.replyTime,jdbcType=TIMESTAMP} REPLY_TIME, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=TIMESTAMP} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.submitCount,jdbcType=DECIMAL} SUBMIT_COUNT, #{item.submitType,jdbcType=VARCHAR} SUBMIT_TYPE from dual
) TEMP where not exists (select 1 from CHB_INFO_REPORT CII where CII.REPORT_NO = TEMP.REPORT_NO) ) de ;
UPDATE CHB_INFO_REPORT as A, ( select TEMP.* from (
select #{item.reportNo,jdbcType=VARCHAR} REPORT_NO, #{item.repMesNo,jdbcType=VARCHAR} REP_MES_NO, #{item.uploadResult,jdbcType=VARCHAR} UPLOAD_RESULT, #{item.uploadResultMsg,jdbcType=VARCHAR} UPLOAD_RESULT_MSG, #{item.uploadFileId,jdbcType=VARCHAR} UPLOAD_FILE_ID, #{item.checkFileId,jdbcType=VARCHAR} CHECK_FILE_ID, #{item.checkResult,jdbcType=VARCHAR} CHECK_RESULT, #{item.checkResultMsg,jdbcType=VARCHAR} CHECK_RESULT_MSG, #{item.checkFileName,jdbcType=VARCHAR} CHECK_FILE_NAME, #{item.checkTotalCount,jdbcType=DECIMAL} CHECK_TOTAL_COUNT, #{item.checkSuccessCount,jdbcType=DECIMAL} CHECK_SUCCESS_COUNT, #{item.checkFailedCount,jdbcType=DECIMAL} CHECK_FAILED_COUNT, #{item.insideFileId,jdbcType=VARCHAR} INSIDE_FILE_ID, #{item.sendTime,jdbcType=DATE} SEND_TIME, #{item.replyTime,jdbcType=TIMESTAMP} REPLY_TIME, #{item.workflowId,jdbcType=VARCHAR} WORKFLOW_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=TIMESTAMP} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.submitCount,jdbcType=DECIMAL} SUBMIT_COUNT, #{item.submitType,jdbcType=VARCHAR} SUBMIT_TYPE from dual
) TEMP ) AS B set A.REPORT_NO=B.REPORT_NO, A.REP_MES_NO=B.REP_MES_NO, A.UPLOAD_RESULT=B.UPLOAD_RESULT, A.UPLOAD_RESULT_MSG=B.UPLOAD_RESULT_MSG, A.UPLOAD_FILE_ID=B.UPLOAD_FILE_ID, A.CHECK_FILE_ID=B.CHECK_FILE_ID, A.CHECK_RESULT=B.CHECK_RESULT, A.CHECK_RESULT_MSG=B.CHECK_RESULT_MSG, A.CHECK_FILE_NAME=B.CHECK_FILE_NAME, A.CHECK_TOTAL_COUNT=B.CHECK_TOTAL_COUNT, A.CHECK_SUCCESS_COUNT=B.CHECK_SUCCESS_COUNT, A.CHECK_FAILED_COUNT=B.CHECK_FAILED_COUNT, A.INSIDE_FILE_ID=B.INSIDE_FILE_ID, A.SEND_TIME=B.SEND_TIME, A.REPLY_TIME=B.REPLY_TIME, A.WORKFLOW_ID=B.WORKFLOW_ID, A.CREATE_USER=B.CREATE_USER, A.CREATE_DEPT=B.CREATE_DEPT, A.CREATE_TIME=B.CREATE_TIME, A.UPDATE_USER=B.UPDATE_USER, A.UPDATE_TIME=B.UPDATE_TIME, A.SUBMIT_COUNT=B.SUBMIT_COUNT, A.SUBMIT_TYPE=B.SUBMIT_TYPE where A.REPORT_NO = B.REPORT_NO;

insert into CHB_SUBMIT_STATUS_TWO(SEQNO,SUBMIT_NUM,SUBMIT_TYPE,SUBMIT_FEEDBACK_STATUS, CREATE_USER,CREATE_DEPT,CREATE_TIME,UPDATE_USER, UPDATE_TIME,REPORT_NO,SUBMIT_FEEDBACK_MSG,UNIQUE_IDENTI) select de.* from ( select TEMP.* from (
select #{item.seqno,jdbcType=VARCHAR} SEQNO, #{item.submitNum,jdbcType=VARCHAR} SUBMIT_NUM, #{item.submitType,jdbcType=VARCHAR} SUBMIT_TYPE, #{item.submitFeedbackStatus,jdbcType=VARCHAR} SUBMIT_FEEDBACK_STATUS, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=TIMESTAMP} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.reportNo,jdbcType=VARCHAR} REPORT_NO, #{item.submitFeedbackMsg,jdbcType=VARCHAR} SUBMIT_FEEDBACK_MSG, #{item.uniqueIdenti,jdbcType=VARCHAR} UNIQUE_IDENTI from dual
) TEMP where not exists (select 1 from CHB_SUBMIT_STATUS_TWO CII where CII.SEQNO = TEMP.SEQNO) ) de ;
UPDATE CHB_SUBMIT_STATUS_TWO as A, ( select TEMP.* from (
select #{item.seqno,jdbcType=VARCHAR} SEQNO, #{item.submitNum,jdbcType=VARCHAR} SUBMIT_NUM, #{item.submitType,jdbcType=VARCHAR} SUBMIT_TYPE, #{item.submitFeedbackStatus,jdbcType=VARCHAR} SUBMIT_FEEDBACK_STATUS, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=TIMESTAMP} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.reportNo,jdbcType=VARCHAR} REPORT_NO, #{item.submitFeedbackMsg,jdbcType=VARCHAR} SUBMIT_FEEDBACK_MSG, #{item.uniqueIdenti,jdbcType=VARCHAR} UNIQUE_IDENTI from dual
) TEMP ) AS B set A.SUBMIT_NUM = B.SUBMIT_NUM, A.SUBMIT_TYPE = B.SUBMIT_TYPE, A.SUBMIT_FEEDBACK_STATUS = B.SUBMIT_FEEDBACK_STATUS, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.CREATE_USER = B.CREATE_USER, A.CREATE_TIME = B.CREATE_TIME, A.REPORT_NO = B.REPORT_NO, A.SUBMIT_FEEDBACK_MSG = B.SUBMIT_FEEDBACK_MSG, A.UNIQUE_IDENTI = B.UNIQUE_IDENTI, A.CREATE_DEPT = B.CREATE_DEPT where A.SEQNO = B.SEQNO;
